#   MUTS="0 1 .." optional overrides)
set -u
cd "${LP_ROOT:-$(git -C "$(dirname "$0")" rev-parse --show-toplevel 2>/dev/null || (cd "$(dirname "$0")/../../../../../.." && pwd))}"
OUT=${1:-lp_bench_out}; mkdir -p "$OUT"; SIM=${SIM:-iverilog}; rc=0
SRCS="rtl/dsrom_sys/s81_dv/svc_rs/attw/dsdv_svc_attw_f.sv rtl/hdc/v41x/ot_hdc_v41x_attn_hgrp_s81.sv rtl/hdc/v41x/ot_hdc_v41x_attn_tile_s.sv rtl/hdc/v41x/ot_hdc_v41x_attn_s.sv rtl/hdc/v41x/ot_hdc_v41x_kreg.sv rtl/hdc/v41x/ot_hdc_v41x_attn_tile_lat.sv rtl/hdc/v41x/ot_hdc_v41x_attn_tile.sv rtl/hdc/v41x/ot_hdc_v41x_attn.sv rtl/hdc/v41x/ot_hdc_v41x_attn_staging.sv physical/asap7_memory_macros/ot_sram_1r1w_256x256_m2_r2c2/ot_sram_1r1w_256x256_m2_r2c2.v physical/asap7_memory_macros/ot_sram_1r1w_32x128_m1/ot_sram_1r1w_32x128_m1.v rtl/hdc/ot_hdc_fastfp.sv rtl/hdc/ot_hdc_fp32_add_lat.sv rtl/hdc/ot_hdc_prefix.sv rtl/hdc/ot_hdc_fp32_f12.sv rtl/hdc/v41x/ot_dsrom_su_add6.sv rtl/hdc/ot_hdc_delay.sv rtl/dsrom_sys/s81_ctrl/ot_s81_svc_job.sv rtl/hdc/ot_hdc_fastfp_lat_f12.sv rtl/hdc/ot_hdc_fp32_mul_lat.sv rtl/dsrom_sys/s81_dv/svc_rs/dsdv_svc_att.sv rtl/dsrom_sys/s81_dv/svc_rs/dsdv_svc_rs_glue.sv rtl/common/landed_parent/ot_pl_land.sv rtl/dsrom_sys/s81_dv/svc_rs/attw/lp/dsdv_svc_attw_f_lp.sv rtl/dsrom_sys/s81_dv/svc_rs/attw/lp/tb_dsdv_svc_attw_f_lp.sv"
python3 tools/landed_parent/lp.py audit tools/landed_parent/specs/dsdv_svc_attw_f.json > "$OUT/audit.log" 2>&1 && echo "AUDIT PASS" || { echo "AUDIT FAIL"; rc=1; }
python3 tools/landed_parent/lp.py audit tools/landed_parent/specs/dsdv_svc_attw_f.json --rtl "$OUT/unland.sv" --make-unland > "$OUT/audit_unland.log" 2>&1 \
  && { echo "AUDIT-UNLAND PASSED (should FAIL)"; rc=1; } || echo "AUDIT-UNLAND FAIL (expected)"
