  if [ "$SIM" = verilator ]; then
    ${VERILATOR:-verilator} --binary -j ${VL_JOBS:-8} -I. -Wno-fatal -Wno-lint -Wno-style -Wno-TIMESCALEMOD -Wno-WIDTHCONCAT -O1 ${VL_EXTRA:-} --top-module tb_dsdv_svc_attw_f_lp -GMUT=$m -DOT_ATTN_HGRP_HARD -DOT_SVC_LAND_SRAM -DOT_SVC_ATT_SRAM -DOT_SVC_ATT_PINREG $SRCS -Mdir "$OUT/obj$m" > "$OUT/build_$m.log" 2>&1 \
